-- Perfume, Davi, Levi e Reforma: cada faixa etária passa a ter a sua arte (faixa-<faixa>-1..4.webp), em vez de um conjunto único. Só troca o caminho das imagens, nos 5 idiomas. Publicar o app ANTES de rodar. Marta e Maria não muda.
\set ON_ERROR_STOP on
BEGIN;
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND language IN ('pt-BR','en','es','fr','it') AND band IN ('4-6','7-10','11-13') AND story IS NOT NULL AND story::text LIKE '%/ilustracoes/a-mulher-e-o-perfume/quadros/hd-%';
  IF n <> 15 THEN RAISE EXCEPTION 'a-mulher-e-o-perfume: esperava 15 versões com a arte de partida e encontrei %', n; END IF;
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND language IN ('pt-BR','en','es','fr','it') AND band IN ('4-6','7-10','11-13') AND story IS NOT NULL AND story::text LIKE '%/ilustracoes/davi-e-a-arca/quadros/hd-%';
  IF n <> 15 THEN RAISE EXCEPTION 'davi-e-a-arca: esperava 15 versões com a arte de partida e encontrei %', n; END IF;
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND language IN ('pt-BR','en','es','fr','it') AND band IN ('4-6','7-10','11-13') AND story IS NOT NULL AND story::text LIKE '%/ilustracoes/levi-e-o-banquete/quadros/hd-%';
  IF n <> 15 THEN RAISE EXCEPTION 'levi-e-o-banquete: esperava 15 versões com a arte de partida e encontrei %', n; END IF;
  SELECT count(*) INTO n FROM devotional_kids WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND language IN ('pt-BR','en','es','fr','it') AND band IN ('4-6','7-10','11-13') AND story IS NOT NULL AND story::text LIKE '%/ilustracoes/reforma-protestante/quadros/reforma-%';
  IF n <> 15 THEN RAISE EXCEPTION 'reforma-protestante: esperava 15 versões com a arte de partida e encontrei %', n; END IF;
END $$;
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-', '/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-4-6-')::jsonb WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '4-6' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/a-mulher-e-o-perfume/quadros/hd-%';
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-', '/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-7-10-')::jsonb WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '7-10' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/a-mulher-e-o-perfume/quadros/hd-%';
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/a-mulher-e-o-perfume/quadros/hd-', '/ilustracoes/a-mulher-e-o-perfume/quadros/faixa-11-13-')::jsonb WHERE devotional_id = 'cmvyun7rw0032o72lmlzc68bk' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/a-mulher-e-o-perfume/quadros/hd-%';
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/davi-e-a-arca/quadros/hd-', '/ilustracoes/davi-e-a-arca/quadros/faixa-4-6-')::jsonb WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '4-6' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/davi-e-a-arca/quadros/hd-%';
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/davi-e-a-arca/quadros/hd-', '/ilustracoes/davi-e-a-arca/quadros/faixa-7-10-')::jsonb WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '7-10' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/davi-e-a-arca/quadros/hd-%';
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/davi-e-a-arca/quadros/hd-', '/ilustracoes/davi-e-a-arca/quadros/faixa-11-13-')::jsonb WHERE devotional_id = 'cmvue6llj000koe2lqtw0xdz2' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/davi-e-a-arca/quadros/hd-%';
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/levi-e-o-banquete/quadros/hd-', '/ilustracoes/levi-e-o-banquete/quadros/faixa-4-6-')::jsonb WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '4-6' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/levi-e-o-banquete/quadros/hd-%';
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/levi-e-o-banquete/quadros/hd-', '/ilustracoes/levi-e-o-banquete/quadros/faixa-7-10-')::jsonb WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '7-10' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/levi-e-o-banquete/quadros/hd-%';
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/levi-e-o-banquete/quadros/hd-', '/ilustracoes/levi-e-o-banquete/quadros/faixa-11-13-')::jsonb WHERE devotional_id = 'cmvv1whpq0002pm2l3f1bfo13' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/levi-e-o-banquete/quadros/hd-%';
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/reforma-protestante/quadros/reforma-', '/ilustracoes/reforma-protestante/quadros/faixa-4-6-')::jsonb WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '4-6' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/reforma-protestante/quadros/reforma-%';
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/reforma-protestante/quadros/reforma-', '/ilustracoes/reforma-protestante/quadros/faixa-7-10-')::jsonb WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '7-10' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/reforma-protestante/quadros/reforma-%';
UPDATE devotional_kids SET story = replace(story::text, '/ilustracoes/reforma-protestante/quadros/reforma-', '/ilustracoes/reforma-protestante/quadros/faixa-11-13-')::jsonb WHERE devotional_id = 'cmvudrag10002oe2ldyzmvhaa' AND band = '11-13' AND language IN ('pt-BR','en','es','fr','it') AND story::text LIKE '%/ilustracoes/reforma-protestante/quadros/reforma-%';
SELECT devotional_id, band, count(*) AS versoes, bool_and(story::text LIKE '%/quadros/faixa-%') AS arte_ok FROM devotional_kids WHERE devotional_id IN ('cmvyun7rw0032o72lmlzc68bk','cmvue6llj000koe2lqtw0xdz2','cmvv1whpq0002pm2l3f1bfo13','cmvudrag10002oe2ldyzmvhaa') AND language IN ('pt-BR','en','es','fr','it') AND story IS NOT NULL GROUP BY 1,2 ORDER BY 1,2;
COMMIT;
